15	// The stale-fixture signal (DEVDESK-573, step 6 of the DEVDESK-511 plan, Q3 (a)).
16	//
17	// The reference is internal/nexusbench/descriptor.json, the versioned descriptor
18	// the bench writes from the instance's own answer. It is NOT
19	// testdata/descriptor.example.json, which is a constant of a test and would not
20	// move when the bench does. The descriptor is decoded here for three fields only:
21	// this package does not import nexusbench, and nexusbench does not import this
22	// package, so no import cycle can appear and no production code reaches the
23	// fixtures. The comparison lives in this test file for the same reason.
24	
25	const (
26		// recordCommand is the command a stale fixture asks for. The task is delivered
27		// by step 8 of the plan.
28		recordCommand = "mise run nexus-bench:record"
29		// descriptorPath is the bench descriptor, relative to this package.
30		descriptorPath = "../nexusbench/descriptor.json"
31		// descriptorSchema is the only descriptor schema this test knows how to read.
32		descriptorSchema = 2
33	)
34	
35	// benchVersion is what the bench descriptor says about the instance.
36	type benchVersion struct {
37		Nexus, Edition string
38	}
39	
40	func (b benchVersion) String() string { return b.Nexus + " " + b.Edition }
41	
42	// readBenchVersion reads nexusVersion and edition from a descriptor file. An
43	// unreadable file, a schema other than descriptorSchema or an empty field is an
44	// error that names the path.
45	func readBenchVersion(path string) (benchVersion, error) {
46		data, err := os.ReadFile(path)
47		if err != nil {
48			return benchVersion{}, fmt.Errorf("cannot read the bench descriptor %s: %w", path, err)
49		}
50		var d struct {
51			SchemaVersion int    `json:"schemaVersion"`
52			NexusVersion  string `json:"nexusVersion"`
53			Edition       string `json:"edition"`
54		}
55		if err := json.Unmarshal(data, &d); err != nil {
56			return benchVersion{}, fmt.Errorf("cannot decode the bench descriptor %s: %w", path, err)
57		}
58		if d.SchemaVersion != descriptorSchema {
59			return benchVersion{}, fmt.Errorf("the bench descriptor %s has schemaVersion %d, this test reads %d: update it with the descriptor schema",
60				path, d.SchemaVersion, descriptorSchema)
61		}
62		if d.NexusVersion == "" || d.Edition == "" {
63			return benchVersion{}, fmt.Errorf("the bench descriptor %s has no nexusVersion or edition (%q, %q)", path, d.NexusVersion, d.Edition)
64		}
65		return benchVersion{Nexus: d.NexusVersion, Edition: d.Edition}, nil
66	}
67	
68	// staleFixtures returns the fixtures whose recorded Nexus version or edition is
69	// not the bench's, in the order given. A pending fixture has no recorded answer
70	// yet, so there is nothing in it to be stale: it is skipped (Load refuses it
71	// anyway). A fixture with no version, or no edition, is stale: its provenance
72	// cannot be told to match.
73	func staleFixtures(fixtures []nexusfixture.Fixture, bench benchVersion) []nexusfixture.Fixture {
74		var stale []nexusfixture.Fixture
75		for _, f := range fixtures {
76			if f.Meta.Record == nexusfixture.RecordPending {
77				continue
78			}
79			if f.Meta.NexusVersion != bench.Nexus || f.Meta.Edition != bench.Edition {
80				stale = append(stale, f)
81			}
82		}
83		return stale
84	}
85	
86	// staleMessage is the failure text for a non-empty stale set: the count per
87	// campaign, every fixture with the version it carries, the version the bench
88	// has, and the command that regenerates them.
89	func staleMessage(stale []nexusfixture.Fixture, bench benchVersion) string {
90		perCampaign := map[string]int{}
91		for _, f := range stale {
92			perCampaign[f.Campaign]++
93		}
94		campaigns := make([]string, 0, len(perCampaign))
95		for c := range perCampaign {
96			campaigns = append(campaigns, c)
97		}
98		sort.Strings(campaigns)
99		counts := make([]string, 0, len(campaigns))
100		for _, c := range campaigns {
101			counts = append(counts, fmt.Sprintf("%s: %d", c, perCampaign[c]))
102		}
103	
104		var b strings.Builder
105		fmt.Fprintf(&b, "%d recorded fixture(s) are stale (%s): the bench descriptor says Nexus %s, they say otherwise.\n",
106			len(stale), strings.Join(counts, ", "), bench)
107		for _, f := range stale {
108			carried := strings.TrimSpace(f.Meta.NexusVersion + " " + f.Meta.Edition)
109			if carried == "" {
110				carried = "no version"
111			}
112			fmt.Fprintf(&b, "  %s/%s: %s, bench: %s\n", f.Campaign, f.Name, carried, bench)
113		}
114		fmt.Fprintf(&b, "Regenerate them against the bench with `%s` and commit the result.", recordCommand)
115		return b.String()
116	}
