118	// fixtureAt builds a synthetic fixture.
119	func fixtureAt(campaign, name, version, edition, record string) nexusfixture.Fixture {
120		return nexusfixture.Fixture{
121			Campaign: campaign,
122			Name:     name,
123			Meta:     nexusfixture.Meta{NexusVersion: version, Edition: edition, Record: record},
124		}
125	}
