135	// TestFixturesMatchTheBenchVersion is the signal itself: every embedded
136	// fixture was recorded against the Nexus the bench descriptor describes. When
137	// the bench moves to another Nexus this test turns red, on purpose: the
138	// fixtures are regenerated in the same change.
139	func TestFixturesMatchTheBenchVersion(t *testing.T) {
140		bench, err := readBenchVersion(filepath.FromSlash(descriptorPath))
141		if err != nil {
142			t.Fatal(err)
143		}
144		fixtures, err := nexusfixture.All()
145		if err != nil {
146			t.Fatalf("All: %v", err)
