148		if len(fixtures) == 0 {
149			t.Fatal("no embedded fixture: the stale check would pass on nothing")
150		}
151		if stale := staleFixtures(fixtures, bench); len(stale) > 0 {
152			t.Fatal("\n" + staleMessage(stale, bench))
153		}
154	}
