26	// The fixture recorder (DEVDESK-511, step 7). RecordFixtures replays the request
27	// of each recorded fixture against the bench and writes the redacted answer back
28	// to the same file. It sends the bench credentials, so everything that could go
29	// wrong is refused before the first fixture request, and nothing is written
30	// unless every answer passed: GET only, a closed list of paths, loopback origins
31	// only, no redirection, a leak check of what will be written.
32	
33	const (
34		// recordedBy is the value of the "recorded-by" header the recorder sets.
35		recordedBy = "nexus-bench record"
36		// recordedFileMode and recordedDirMode are the modes of a written fixture.
37		recordedFileMode os.FileMode = 0o644
38		recordedDirMode  os.FileMode = 0o755
39		// recordedDateLayout is the date of the "measured" header.
40		recordedDateLayout = "2006-01-02"
41	
42		benchUpCall = "run `mise run nexus-bench:up` so the bench runs the version the descriptor names"
43	)
44	
45	// RecordOptions says what to record and against which bench.
46	type RecordOptions struct {
47		// Origins maps the Host of a fixture ("127.0.0.1:30481") to the base URL that
48		// reaches it. Each key must be a loopback host:port of the descriptor and each
49		// URL a loopback origin (IsLoopbackRESTHost), no user information. The REST
50		// origin (first host of the descriptor, REST node port) is required: the data
51		// set is compared through it.
52		Origins    map[string]string
53		Descriptor Descriptor
54		Secrets    Secrets
55		// Dir is the folder of the campaigns; empty means nexusfixture.SourceDir().
56		Dir string
57		// Campaigns limits the run to these campaigns; empty means every folder of Dir.
58		Campaigns []string
59		// Only is an optional glob (path.Match) on fixture names, without ".http".
60		Only string
61		// Now gives the date of the "measured" header; nil means time.Now.
62		Now func() time.Time
63		// DenyTerms are extra terms no written fixture may hold (the external deny list).
64		DenyTerms []string
65	}
66	
67	// RecordReport lists the fixtures of a run as "<campaign>/<name>". A Skipped
68	// entry is followed by ": <reason>".
69	type RecordReport struct {
70		Written, Unchanged, Skipped []string
71	}
72	
73	// recordJob is one fixture to replay.
74	type recordJob struct {
75		campaign string
76		name     string // "<campaign>/<file name without .http>"
77		path     string
78		current  nexusfixture.Fixture
79		user     string // "" for an anonymous fixture
80		password string
81		origin   string
82	}
83	
84	// recordWrite is a fixture file to replace, held back until every answer passed.
85	type recordWrite struct {
86		name string
87		path string
88		data []byte
89	}
90	
91	// RecordFixtures regenerates the recorded fixtures from the bench. A fixture is
92	// skipped (reported, never requested) when it says "record: skip" or holds more
93	// than one exchange. A fixture whose answer is the one it already holds, apart
94	// from its date, is left alone, bytes and modification time. Every error is a
95	// *BenchError, free of secrets; on an error nothing is written and the report is
96	// empty.
97	func RecordFixtures(ctx context.Context, o RecordOptions) (RecordReport, error) {
98		if err := ctx.Err(); err != nil {
99			return RecordReport{}, recordError("the recording was cancelled before it started", "run it again", err)
100		}
101		jobs, report, err := planRecording(o)
102		if err != nil {
103			return RecordReport{}, err
104		}
105		if len(jobs) > 0 {
106			if err := checkBenchDataset(ctx, o); err != nil {
107				return RecordReport{}, err
108			}
109		}
110		writes, unchanged, err := gatherAnswers(ctx, o, jobs)
111		if err != nil {
112			return RecordReport{}, err
113		}
114		report.Unchanged = unchanged
115		for i, w := range writes {
116			if err := writeFileAtomic(w.path, w.data, recordedFileMode, recordedDirMode); err != nil {
117				return RecordReport{}, recordError(
118					fmt.Sprintf("%s could not be written (%d fixture(s) of this run were already written)", w.name, i),
119					"check the permissions of the fixtures folder, then record again", err)
120			}
121			report.Written = append(report.Written, w.name)
122		}
123		return report, nil
124	}
125	
126	// recordError returns a BenchError; err is kept for errors.Is and errors.As and
127	// is never printed. A refusal with no underlying error keeps its own cause.
128	func recordError(cause, check string, err error) *BenchError {
129		if err == nil {
130			err = errors.New(cause)
131		}
132		return &BenchError{Kind: Unclassified, Cause: cause, Check: check, Err: err}
133	}
134	
135	// ---- planning: everything is checked before the first request ------------------
136	
137	// planRecording reads the fixtures and refuses anything that must not be sent.
138	func planRecording(o RecordOptions) ([]recordJob, RecordReport, error) {
139		var report RecordReport
140		if err := checkOrigins(o); err != nil {
141			return nil, report, err
142		}
143		if o.Only != "" {
144			if _, err := path.Match(o.Only, ""); err != nil {
145				return nil, report, recordError("the fixture filter is not a valid glob", "write it as a path.Match pattern, e.g. catalog-*", err)
146			}
147		}
148		dir := o.Dir
149		if dir == "" {
150			var err error
151			if dir, err = nexusfixture.SourceDir(); err != nil {
152				return nil, report, recordError("the fixtures folder of the source tree cannot be located", "run the recorder from a build that knows its source tree (not -trimpath)", err)
153			}
154		}
155		if info, err := os.Stat(dir); err != nil || !info.IsDir() {
156			return nil, report, recordError("the fixtures folder "+dir+" is not there", "check the folder", err)
157		}
158		fsys := os.DirFS(dir)
159		campaigns, err := recordCampaigns(fsys, o.Campaigns)
160		if err != nil {
161			return nil, report, err
162		}
163		var jobs []recordJob
164		for _, campaign := range campaigns {
165			entries, err := fs.ReadDir(fsys, campaign)
166			if err != nil {
167				return nil, report, recordError("the campaign "+campaign+" cannot be read", "check the fixtures folder", err)
168			}
169			for _, e := range entries {
170				name, ok := strings.CutSuffix(e.Name(), ".http")
171				if e.IsDir() || !ok {
172					continue
173				}
174				if o.Only != "" {
175					if match, _ := path.Match(o.Only, name); !match {
176						continue
177					}
178				}
179				job, skipped, err := planFixture(o, fsys, filepath.Join(dir, campaign, e.Name()), campaign, e.Name())
180				switch {
181				case err != nil:
182					return nil, report, err
183				case skipped != "":
184					report.Skipped = append(report.Skipped, campaign+"/"+name+": "+skipped)
185				default:
186					jobs = append(jobs, job)
187				}
188			}
189		}
190		return jobs, report, nil
191	}
192	
193	// recordCampaigns returns the campaigns to read: the ones asked for, each a plain
194	// folder name of fsys, or every folder of fsys.
195	func recordCampaigns(fsys fs.FS, wanted []string) ([]string, error) {
196		if len(wanted) == 0 {
197			entries, err := fs.ReadDir(fsys, ".")
198			if err != nil {
199				return nil, recordError("the fixtures folder cannot be read", "check the folder", err)
200			}
201			var all []string
202			for _, e := range entries {
203				if e.IsDir() && !strings.HasPrefix(e.Name(), ".") {
204					all = append(all, e.Name())
205				}
206			}
207			return all, nil
208		}
209		for _, c := range wanted {
210			if c == "." || !fs.ValidPath(c) || strings.Contains(c, "/") {
211				return nil, recordError("the campaign "+strconv.Quote(c)+" is not a campaign name", "name a folder of the fixtures folder, with no path", nil)
212			}
213			if info, err := fs.Stat(fsys, c); err != nil || !info.IsDir() {
214				return nil, recordError("the campaign "+c+" does not exist", "check the campaign name", err)
215			}
216		}
217		return wanted, nil
218	}
219	
220	// planFixture reads one fixture file. It returns the reason when the fixture is
221	// skipped, an error when it must not be sent.
222	func planFixture(o RecordOptions, fsys fs.FS, filePath, campaign, fileName string) (recordJob, string, error) {
223		label := campaign + "/" + strings.TrimSuffix(fileName, ".http")
224		data, err := fs.ReadFile(fsys, path.Join(campaign, fileName))
225		if err != nil {
226			return recordJob{}, "", recordError(label+" cannot be read", "check the file", err)
227		}
228		f, err := nexusfixture.Parse(campaign, fileName, data)
229		if err != nil {
230			return recordJob{}, "", recordError(label+" is not a valid fixture", "fix the file: "+err.Error(), err)
231		}
232		if reason, ok := strings.CutPrefix(f.Meta.Record, "skip"); ok {
233			return recordJob{}, strings.TrimSpace(strings.TrimPrefix(reason, ":")), nil
234		}
235		if len(f.Exchanges) != 1 {
236			return recordJob{}, fmt.Sprintf("holds %d exchanges, only one is recorded yet", len(f.Exchanges)), nil
237		}
238		// The file is scanned as it stands: a request header outside Host, the
239		// credentials and Accept, or a query other than n and last, refuses it.
240		if leaks := nexusfixture.CheckLeaks(label, data, recordTerms(o)); len(leaks) > 0 {
241			return recordJob{}, "", recordError(label+" is refused before it is sent: "+describeLeaks(leaks), "fix the file", nil)
242		}
243		ex := f.Exchanges[0]
244		if reason := refusedRequest(ex.Method, ex.Target); reason != "" {
245			return recordJob{}, "", recordError(label+" asks for something the recorder does not send ("+reason+")", "record only GET requests of the closed list of paths", nil)
246		}
247		origin, ok := o.Origins[ex.Host]
248		if !ok {
249			return recordJob{}, "", recordError(label+" is recorded on "+ex.Host+", which has no origin", "give the origin of this host:port", nil)
250		}
251		job := recordJob{campaign: campaign, name: label, path: filePath, current: f, origin: origin}
252		switch f.Identity {
253		case nexusfixture.Admin:
254			job.user, job.password = REDACTED, o.Secrets.AdminPassword
255		case nexusfixture.Pull:
256			job.user, job.password = REDACTED, o.Secrets.PullPassword
257		}
258		if job.user != "" && job.password == "" {
259			return recordJob{}, "", recordError("the bench has no stored password for "+job.user+", the account of "+label, upCheck, nil)
260		}
261		return job, "", nil
262	}
263	
264	// checkOrigins refuses an origin that is not a loopback URL, a key that is not a
265	// loopback host:port of the descriptor, and a run with no REST origin.
266	func checkOrigins(o RecordOptions) error {
267		known := descriptorOrigins(o.Descriptor)
268		for key, base := range o.Origins {
269			if !known[key] {
270				return recordError("the origin of "+key+" is not a loopback host:port of the bench descriptor", "give origins for the hosts and ports the descriptor lists", nil)
271			}
272			if err := requireLoopbackBase(base); err != nil {
273				return err
274			}
275		}
276		rest, ok := restOriginKey(o.Descriptor)
277		if _, have := o.Origins[rest]; !ok || !have {
278			return recordError("no origin is given for the REST port of the bench, which the data set check needs", "give the REST origin of the descriptor", nil)
279		}
280		return nil
281	}
282	
283	// descriptorOrigins is the set of loopback host:port pairs the descriptor
284	// publishes: every host of the descriptor on the REST and the Docker ports.
285	func descriptorOrigins(d Descriptor) map[string]bool {
286		ports := []int{d.REST.NodePort}
287		for _, c := range d.DockerConnectors {
288			ports = append(ports, c.NodePort)
289		}
290		known := map[string]bool{}
291		for _, h := range d.Hosts {
292			host := strings.Trim(h, "[]")
293			if !IsLoopbackRESTHost(host) {
294				continue
295			}
296			for _, p := range ports {
297				known[net.JoinHostPort(host, strconv.Itoa(p))] = true
298			}
299		}
300		return known
301	}
302	
303	// restOriginKey is the host:port of the REST API: the first host of the
304	// descriptor on the REST node port.
305	func restOriginKey(d Descriptor) (string, bool) {
306		if len(d.Hosts) == 0 || d.REST.NodePort == 0 {
307			return "", false
308		}
309		return net.JoinHostPort(strings.Trim(d.Hosts[0], "[]"), strconv.Itoa(d.REST.NodePort)), true
310	}
311	
312	// The closed list of what the recorder may ask for. A manifest or a blob read
313	// through a proxy repository would cache an image and change the bench, so none
314	// is allowed, whatever the path says.
315	var (
316		recordPaths = []*regexp.Regexp{
317			regexp.MustCompile(`^/v2/(_catalog|[a-z0-9._/-]+/tags/list)?$`),
318			regexp.MustCompile(`^/repository/[A-Za-z0-9._-]+/v2/_catalog$`),
319			regexp.MustCompile(`^/service/rest/v1/repositories(/[A-Za-z0-9._-]+)*$`),
320		}
321		recordQueryParam = regexp.MustCompile(`^(n=[0-9]{1,6}|last=[A-Za-z0-9._/-]*)$`)
322	)
323	
324	// refusedRequest returns why a request may not be sent, or "".
325	func refusedRequest(method, target string) string {
326		p, query, hasQuery := strings.Cut(target, "?")
327		switch {
328		case method != http.MethodGet:
329			return "the method is not GET"
330		case strings.Contains(target, "..") || strings.Contains(target, "%"):
331			return "the target holds a dot-dot or an escape"
332		case strings.Contains(p+"/", "/manifests/") || strings.Contains(p+"/", "/blobs/"):
333			return "a manifest or a blob read can change the bench"
334		}
335		listed := false
336		for _, re := range recordPaths {
337			listed = listed || re.MatchString(p)
338		}
339		if !listed {
340			return "the path is not in the closed list"
341		}
342		if hasQuery {
343			for _, param := range strings.Split(query, "&") {
344				if !recordQueryParam.MatchString(param) {
345					return "the query holds more than n and last"
346				}
347			}
348		}
349		return ""
350	}
